from pathlib import Path
import base64, hashlib, json, zlib

root = Path(__file__).resolve().parents[1]
p = root / "index.html"
text = p.read_text(encoding="utf-8")
OLD_SHA = "91a9c30132813ed60b79caa7c639bbba93587690a0efbdc7493afdca39d1d58a"
NEW_SHA = "1e8d53e9b3b2f9d08027b51c43b9f6088d92c7466da5030fdeccaf8db08e9caf"
current = hashlib.sha256(text.encode("utf-8")).hexdigest()
if current == NEW_SHA:
    print("Report already up to date")
    raise SystemExit(0)
if current != OLD_SHA:
    raise SystemExit(f"Unexpected index baseline: {current}")
ops = json.loads(zlib.decompress(base64.b64decode("")).decode("utf-8"))
lines = text.splitlines(keepends=True)
for i1, i2, replacement in reversed(ops):
    lines[i1:i2] = replacement.splitlines(keepends=True)
out = "".join(lines)
actual = hashlib.sha256(out.encode("utf-8")).hexdigest()
if actual != NEW_SHA:
    raise SystemExit(f"Patched checksum mismatch: {actual}")
p.write_text(out, encoding="utf-8")
print(f"Patched index.html to {NEW_SHA}")
